set-variable.value:
@{
      try {
          var body = context.Request.Body?.As<JObject>(preserveContent: true);
          var alias = (string)(body?["model"] ?? "fast");
          return string.IsNullOrEmpty(alias) ? "fast" : alias.ToLowerInvariant();
      } catch { return "fast"; }
  }

return-response.set-body:
@{
            return new JObject(
                new JProperty("error", "UNKNOWN_MODEL_ALIAS"),
                new JProperty("message", "Model alias must be one of: fast, balanced, reasoning."),
                new JProperty("correlationId", (string)context.Variables["correlationId"])
            ).ToString();
        }

set-variable.value:
@{
      var tier = (string)context.Variables["consumerTier"];
      var alias = (string)context.Variables["modelAlias"];
      if (tier == "premium") { return true; }
      if (tier == "standard") { return alias == "fast" || alias == "balanced"; }
      return alias == "fast"; // free
  }

return-response.set-body:
@{
            var a = (string)context.Variables["modelAlias"];
            var t = (string)context.Variables["consumerTier"];
            return new JObject(
                new JProperty("error", "MODEL_NOT_ALLOWED_FOR_TIER"),
                new JProperty("message", "Model '" + a + "' is not available for the '" + t + "' tier."),
                new JProperty("consumer", (string)context.Variables["consumerId"]),
                new JProperty("correlationId", (string)context.Variables["correlationId"])
            ).ToString();
        }

set-variable.value:
@{
      try {
          var map = JObject.Parse((string)context.Variables["aliasMapJson"]);
          var alias = (string)context.Variables["modelAlias"];
          return ((string)map[alias] ?? string.Empty).Trim();
      } catch { return string.Empty; }
  }

return-response.set-body:
@{
            return new JObject(
                new JProperty("error", "MODEL_ALIAS_NOT_CONFIGURED"),
                new JProperty("message", "The requested model alias is not currently configured."),
                new JProperty("correlationId", (string)context.Variables["correlationId"])
            ).ToString();
        }
